import React, { useContext, useState } from "react";
import { Button, Card, Container, Image, Table, Row, Col, Spinner } from "react-bootstrap";
import { Context } from "../index";
import { observer } from "mobx-react-lite";
import { SHOP_ROUTE } from "../utils/const";
import { NavLink } from "react-router-dom";
import { useNavigate } from "react-router-dom";

const Bascket = observer(() => {
    const { bascket } = useContext(Context);
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);

    const increaseQuantity = (productId) => {
        bascket.addProduct(productId);
    };

    const decreaseQuantity = (productId) => {
        bascket.removeProduct(productId);
    };

    const removeProduct = (productId) => {
        bascket.deleteProduct(productId);
    };

    const checkout = () => {
        setLoading(true);
        // Здесь будет логика оформления заказа
        setTimeout(() => {
            setLoading(false);
            bascket.clearBascket();
            navigate('/order-success');
        }, 1500);
    };

    return (
        <Container className="mt-4" style={{ minHeight: "70vh" }}>
            <h2 className="mb-4" style={{ color: "#ef960b", fontFamily: "'Dancing Script', cursive" }}>
                Ваша корзина
            </h2>
            
            {bascket.products.length > 0 ? (
                <>
                    <Table striped bordered hover responsive className="align-middle">
                        <thead>
                            <tr>
                                <th style={{ width: "15%" }}>Изображение</th>
                                <th>Название</th>
                                <th>Цена</th>
                                <th>Количество</th>
                                <th>Сумма</th>
                                <th>Действия</th>
                            </tr>
                        </thead>
                        <tbody>
                            {bascket.products.map(product => (
                                <tr key={product.id}>
                                    <td>
                                        <Image 
                                            src={process.env.REACT_APP_API_URL + product.img} 
                                            width={70} 
                                            height={70}
                                            style={{ objectFit: 'cover', borderRadius: '5px' }}
                                        />
                                    </td>
                                    <td>{product.name}</td>
                                    <td>{product.price} ₽</td>
                                    <td>
                                        <Button 
                                            variant="outline-secondary" 
                                            size="sm" 
                                            onClick={() => decreaseQuantity(product.id)}
                                            disabled={product.quantity <= 1}
                                        >
                                            -
                                        </Button>
                                        <span className="mx-2">{product.quantity}</span>
                                        <Button 
                                            variant="outline-secondary" 
                                            size="sm" 
                                            onClick={() => increaseQuantity(product.id)}
                                        >
                                            +
                                        </Button>
                                    </td>
                                    <td>{product.price * product.quantity} ₽</td>
                                    <td>
                                        <Button 
                                            variant="outline-danger" 
                                            size="sm"
                                            onClick={() => removeProduct(product.id)}
                                        >
                                            Удалить
                                        </Button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </Table>

                    <Card className="mt-4 shadow" style={{ backgroundColor: '#f8f9fa' }}>
                        <Card.Body>
                            <Row className="align-items-center">
                                <Col md={6}>
                                    <h4 style={{ color: "#2c3e50" }}>
                                        Итого: <strong>{bascket.totalPrice} ₽</strong>
                                    </h4>
                                </Col>
                                <Col md={6} className="text-end">
                                    <Button 
                                        variant="success" 
                                        size="lg"
                                        onClick={checkout}
                                        disabled={loading}
                                        style={{ 
                                            backgroundColor: '#2ecc71',
                                            borderColor: '#2ecc71',
                                            minWidth: '200px'
                                        }}
                                    >
                                        {loading ? (
                                            <>
                                                <Spinner
                                                    as="span"
                                                    animation="border"
                                                    size="sm"
                                                    role="status"
                                                    aria-hidden="true"
                                                    className="me-2"
                                                />
                                                Оформляем...
                                            </>
                                        ) : 'Оформить заказ'}
                                    </Button>
                                </Col>
                            </Row>
                        </Card.Body>
                    </Card>
                </>
            ) : (
                <Card className="text-center p-5 shadow" style={{ backgroundColor: '#f8f9fa' }}>
                    <Card.Img 
                        variant="top" 
                        src="/corzina.png" 
                        style={{ height: '200px', objectFit: 'contain' }}
                        className="mb-4"
                    />
                    <Card.Body>
                        <Card.Title style={{ color: "#2c3e50" }}>Корзина пуста</Card.Title>
                        <Card.Text className="mt-3" style={{ color: "#7f8c8d" }}>
                            Добавьте товары из нашего меню
                        </Card.Text>
                        <NavLink to={SHOP_ROUTE}>
                            <Button 
                                variant="primary" 
                                className="mt-3"
                                style={{ 
                                    backgroundColor: '#3498db',
                                    borderColor: '#3498db'
                                }}
                            >
                                Перейти в меню
                            </Button>
                        </NavLink>
                    </Card.Body>
                </Card>
            )}
        </Container>
    );
});

export default Bascket;